package com.downloadanything.pro;

import android.app.AlertDialog;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.*;

/** 30-day recycle bin UI. */
public final class TrashActivity extends AppCompatActivity{
    private int BG,CARD,INPUT,GOLD,TEXT,MUTED,OUTLINE;private boolean ar;private LinearLayout list;private final java.util.concurrent.ExecutorService io=RuntimeExecutors.io();
    @Override protected void onCreate(Bundle b){super.onCreate(b);ar=UiPrefs.isArabic(this);UiPrefs.Palette p=UiPrefs.palette(this);BG=p.bg;CARD=p.card;INPUT=p.input;GOLD=p.gold;TEXT=p.text;MUTED=p.muted;OUTLINE=p.outline;setContentView(ui());refresh();}
    @Override protected void onResume(){super.onResume();refresh();}
    private View ui(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setBackgroundColor(BG);r.setPadding(dp(10),dp(12),dp(10),dp(10));LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);Button back=btn("←");back.setOnClickListener(v->finish());h.addView(back,new LinearLayout.LayoutParams(dp(48),dp(44)));TextView t=txt(tr("🗑 سلة المحذوفات","🗑 Trash"),21,TEXT);t.setTypeface(Typeface.DEFAULT_BOLD);h.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));r.addView(h);TextView note=txt(tr("يتم الاحتفاظ بملفات البرنامج المحذوفة لمدة 30 يومًا ثم تُحذف تلقائيًا.","Files deleted by the app are kept for 30 days, then purged automatically."),12,MUTED);note.setPadding(4,2,4,10);r.addView(note);ScrollView s=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);s.addView(list);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));return r;}
    private void refresh(){if(list==null)return;List<TrashStore.Entry>xs=TrashStore.list(this);list.removeAllViews();if(xs.isEmpty()){TextView e=txt(tr("السلة فارغة","Trash is empty"),15,MUTED);e.setGravity(Gravity.CENTER);e.setPadding(0,dp(40),0,0);list.addView(e);return;}long now=System.currentTimeMillis();for(TrashStore.Entry x:xs){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(10),dp(9),dp(10),dp(9));c.setBackground(round(CARD,16));TextView n=txt(x.name,15,TEXT);n.setTypeface(Typeface.DEFAULT_BOLD);c.addView(n);long days=Math.max(0,(x.expiresAt-now+86_399_999L)/86_400_000L);c.addView(txt(fmt(x.size)+" • "+days+" "+tr("يوم متبقٍ","days left"),11,MUTED));LinearLayout a=new LinearLayout(this);Button restore=btn(tr("استعادة","Restore")),del=btn(tr("حذف نهائي","Delete forever"));a.addView(restore,lp(0,40,1,4));a.addView(del,lp(0,40,1,0));c.addView(a);restore.setOnClickListener(v->io.execute(()->{try{TrashStore.restore(this,x);runOnUiThread(()->{Toast.makeText(this,tr("تمت الاستعادة","Restored"),Toast.LENGTH_SHORT).show();refresh();});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,tr("تعذرت الاستعادة","Restore failed"),Toast.LENGTH_SHORT).show());}}));del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage(tr("حذف هذا الملف نهائيًا؟","Delete this file forever?")).setPositiveButton(tr("حذف","Delete"),(d,w)->{TrashStore.remove(this,x);refresh();}).setNegativeButton(tr("إلغاء","Cancel"),null).show());list.addView(c,lp(-1,-2,0,6));}}
    private Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(TEXT);b.setBackground(round(INPUT,12));return b;}private TextView txt(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;}private GradientDrawable round(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));d.setStroke(dp(1),OUTLINE);return d;}private LinearLayout.LayoutParams lp(int w,int h,float wt,int m){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h<0?h:dp(h),wt);p.setMarginEnd(dp(m));p.bottomMargin=dp(m);return p;}private int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}private String tr(String a,String e){return ar?a:e;}private String fmt(long b){return b>=1073741824?String.format(Locale.US,"%.1f GB",b/1073741824d):b>=1048576?String.format(Locale.US,"%.1f MB",b/1048576d):String.format(Locale.US,"%.0f KB",b/1024d);}
}
